SELECT COUNT(DISTINCT m.home_team_api_id) AS distinct_entity_cnt FROM EU_SOCCER.MATCH m;
SELECT m.league_id, COUNT(*) AS event_cnt FROM EU_SOCCER.MATCH m GROUP BY m.league_id ORDER BY event_cnt DESC LIMIT 1000;
SELECT COUNT(*) AS event_cnt FROM EU_SOCCER.MATCH m WHERE CAST(m.date AS DATETIME) >= '2024-01-01 00:00:00' AND CAST(m.date AS DATETIME) < '2024-01-31 23:59:59';
SELECT m.season, COUNT(*) AS event_cnt FROM EU_SOCCER.MATCH m GROUP BY m.season ORDER BY event_cnt DESC LIMIT 1000;
SELECT m.season, AVG(m.B365H) AS avg_home_win_odds FROM EU_SOCCER.MATCH m WHERE m.B365H IS NOT NULL GROUP BY m.season ORDER BY avg_home_win_odds DESC LIMIT 1000;
SELECT m.match_api_id, COUNT(DISTINCT m.home_team_api_id) AS entity_cnt FROM EU_SOCCER.MATCH m GROUP BY m.match_api_id HAVING COUNT(DISTINCT m.home_team_api_id) > 1 ORDER BY entity_cnt DESC LIMIT 3;
WITH a AS ( SELECT DISTINCT ta.team_api_id FROM EU_SOCCER.TEAM_ATTRIBUTES ta WHERE CAST(ta.date AS DATETIME) >= '2012-01-01 00:00:00' AND CAST(ta.date AS DATETIME) < '2013-01-01 00:00:00' ), b AS ( SELECT DISTINCT ta.team_api_id FROM EU_SOCCER.TEAM_ATTRIBUTES ta WHERE CAST(ta.date AS DATETIME) >= '2014-01-01 00:00:00' AND CAST(ta.date AS DATETIME) < '2015-01-01 00:00:00' ) SELECT COUNT(*) AS retained_entity_cnt FROM a JOIN b USING (team_api_id);
SELECT m.season, SUM(CASE WHEN CAST(m.date AS DATETIME) >= '2012-01-01 00:00:00' AND CAST(m.date AS DATETIME) < '2013-01-01 00:00:00' THEN 1 ELSE 0 END) AS curr_cnt, SUM(CASE WHEN CAST(m.date AS DATETIME) >= '2014-01-01 00:00:00' AND CAST(m.date AS DATETIME) < '2015-01-01 00:00:00' THEN 1 ELSE 0 END) AS prev_cnt, ( SUM(CASE WHEN CAST(m.date AS DATETIME) >= '2012-01-01 00:00:00' AND CAST(m.date AS DATETIME) < '2013-01-01 00:00:00' THEN 1 ELSE 0 END) - SUM(CASE WHEN CAST(m.date AS DATETIME) >= '2014-01-01 00:00:00' AND CAST(m.date AS DATETIME) < '2015-01-01 00:00:00' THEN 1 ELSE 0 END) ) AS delta_cnt FROM EU_SOCCER.MATCH m GROUP BY m.season ORDER BY delta_cnt DESC LIMIT 3;
WITH agg AS ( SELECT m.season AS topic, AVG(m.B365H) AS amt FROM EU_SOCCER.MATCH m WHERE m.B365H IS NOT NULL AND CAST(m.date AS DATETIME) >= '2012-01-01 00:00:00' AND CAST(m.date AS DATETIME) < '2013-01-01 00:00:00' GROUP BY m.season ), tot AS ( SELECT SUM(amt) AS total_amt FROM agg ) SELECT topic, amt, amt / NULLIF((SELECT total_amt FROM tot), 0) AS amt_share FROM agg ORDER BY amt_share DESC;
WITH daily AS ( SELECT DATE( CAST(m.date AS DATETIME)) AS d, COUNT(*) AS cnt FROM EU_SOCCER.MATCH m WHERE CAST(m.date AS DATETIME) >= '2012-01-01 00:00:00' AND CAST(m.date AS DATETIME) < '2013-01-01 00:00:00' GROUP BY d ), ma AS ( SELECT d, cnt, AVG(cnt) OVER (ORDER BY d ROWS BETWEEN 7 PRECEDING AND 1 PRECEDING) AS prev_7d_avg FROM daily ) SELECT d, cnt, prev_7d_avg FROM ma WHERE prev_7d_avg IS NOT NULL AND cnt > prev_7d_avg ORDER BY (cnt - prev_7d_avg) DESC LIMIT 3;
SELECT pa.player_api_id, SUM(CASE WHEN pa.attacking_work_rate ='high' or pa.attacking_work_rate ='medium' THEN 1 ELSE 0 END) AS hit_cnt, COUNT(*) AS total_cnt, SUM(CASE WHEN pa.attacking_work_rate ='high' or pa.attacking_work_rate ='medium' THEN 1 ELSE 0 END) / COUNT(*) AS hit_ratio FROM EU_SOCCER.PLAYER_ATTRIBUTES pa GROUP BY pa.player_api_id HAVING COUNT(*) >= 1 ORDER BY hit_ratio DESC LIMIT 3;
SELECT pa.id, COUNT(DISTINCT pa.player_api_id) AS external_cnt FROM EU_SOCCER.PLAYER_ATTRIBUTES pa GROUP BY pa.id HAVING COUNT(DISTINCT pa.player_api_id) > 1 ORDER BY external_cnt DESC LIMIT 10;
WITH agg AS ( SELECT ta.buildUpPlaySpeedClass AS topic, t.team_long_name AS entity_name, COUNT(*) AS qty FROM EU_SOCCER.TEAM_ATTRIBUTES ta JOIN EU_SOCCER.TEAM t ON ta.team_api_id = t.team_api_id GROUP BY ta.buildUpPlaySpeedClass, t.team_long_name ), ranked AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY topic ORDER BY qty DESC, entity_name) AS rn FROM agg ) SELECT topic, entity_name, qty FROM ranked WHERE rn = 1 ORDER BY qty DESC;
SELECT c.name AS location, m.season AS category_topic, COUNT(*) AS event_cnt FROM EU_SOCCER.MATCH m JOIN EU_SOCCER.LEAGUE l ON m.league_id = l.id JOIN EU_SOCCER.COUNTRY c ON l.country_id = c.id GROUP BY c.name, m.season HAVING COUNT(*) >= 5 ORDER BY event_cnt DESC LIMIT 20;
SELECT COUNT(DISTINCT fie.FEDERAL_REGULATOR) AS distinct_entity_cnt FROM FINANCE__ECONOMICS.CYBERSYN_FINANCIAL_INSTITUTION_ENTITIES fie;
SELECT c.ID_STATE, COUNT(*) AS event_cnt FROM FINANCE__ECONOMICS.CYBERSYN_FINANCIAL_CFPB_COMPLAINT c GROUP BY c.ID_STATE ORDER BY event_cnt DESC LIMIT 1000;
SELECT COUNT(*) AS event_cnt FROM FINANCE__ECONOMICS.CYBERSYN_FINANCIAL_CFPB_COMPLAINT c WHERE c.DATE_RECEIVED >= '2024-01-01 00:00:00' AND c.DATE_RECEIVED < '2024-01-31 23:59:59';
SELECT c.PRODUCT, COUNT(*) AS event_cnt FROM FINANCE__ECONOMICS.CYBERSYN_FINANCIAL_CFPB_COMPLAINT c GROUP BY c.PRODUCT ORDER BY event_cnt DESC LIMIT 1000;
SELECT s.ASSET_CLASS, SUM(s.VALUE) AS total_amount FROM FINANCE__ECONOMICS.CYBERSYN_STOCK_PRICE_TIMESERIES s GROUP BY s.ASSET_CLASS ORDER BY total_amount DESC LIMIT 1000;
SELECT e.ID_RSSD_PREDECESSOR, COUNT(DISTINCT e.CATEGORY_SUCCESSOR) AS entity_cnt FROM FINANCE__ECONOMICS.CYBERSYN_FINANCIAL_INSTITUTION_EVENTS e GROUP BY e.ID_RSSD_PREDECESSOR HAVING COUNT(DISTINCT e.CATEGORY_SUCCESSOR) > 1 ORDER BY entity_cnt DESC LIMIT 3;
WITH a AS ( SELECT DISTINCT t.ID_RSSD FROM FINANCE__ECONOMICS.CYBERSYN_FINANCIAL_INSTITUTION_TIMESERIES t WHERE t.DATE >= '2025-06-01' AND t.DATE < '2025-07-01' ), b AS ( SELECT DISTINCT t.ID_RSSD FROM FINANCE__ECONOMICS.CYBERSYN_FINANCIAL_INSTITUTION_TIMESERIES t WHERE t.DATE >= '2025-12-01' AND t.DATE < '2026-01-01' ) SELECT COUNT(*) AS retained_entity_cnt FROM a JOIN b USING (ID_RSSD);
WITH agg AS ( SELECT s.ASSET_CLASS AS topic, SUM(s.VALUE) AS amt FROM FINANCE__ECONOMICS.CYBERSYN_STOCK_PRICE_TIMESERIES s WHERE CAST(s.DATE AS DATETIME) >= '2024-11-01' AND CAST(s.DATE AS DATETIME) < '2024-12-01' GROUP BY s.ASSET_CLASS ), tot AS ( SELECT SUM(amt) AS total_amt FROM agg ) SELECT topic, amt, amt / NULLIF((SELECT total_amt FROM tot), 0) AS amt_share FROM agg ORDER BY amt_share DESC;
WITH daily AS ( SELECT DATE( c.DATE_RECEIVED) AS d, COUNT(*) AS cnt FROM FINANCE__ECONOMICS.CYBERSYN_FINANCIAL_CFPB_COMPLAINT c WHERE CAST(c.DATE_RECEIVED AS DATETIME) >= '2024-07-01' AND CAST(c.DATE_RECEIVED AS DATETIME) < '2024-07-31' GROUP BY d ), ma AS ( SELECT d, cnt, AVG(cnt) OVER (ORDER BY d ROWS BETWEEN 7 PRECEDING AND 1 PRECEDING) AS prev_7d_avg FROM daily ) SELECT d, cnt, prev_7d_avg FROM ma WHERE prev_7d_avg IS NOT NULL AND cnt > prev_7d_avg ORDER BY (cnt - prev_7d_avg) DESC;
SELECT c.ID_STATE, SUM(CASE WHEN c.TIMELY_RESPONSE = 1 THEN 1 ELSE 0 END) AS hit_cnt, COUNT(*) AS total_cnt, SUM(CASE WHEN c.TIMELY_RESPONSE = 1 THEN 1 ELSE 0 END) / COUNT(*) AS hit_ratio FROM FINANCE__ECONOMICS.CYBERSYN_FINANCIAL_CFPB_COMPLAINT c GROUP BY c.ID_STATE HAVING COUNT(*) >= 50 ORDER BY hit_ratio DESC LIMIT 3;
SELECT ci.COMPANY_ID, COUNT(DISTINCT ci.PERMID_COMPANY_ID) AS external_cnt FROM FINANCE__ECONOMICS.CYBERSYN_COMPANY_INDEX ci GROUP BY ci.COMPANY_ID HAVING COUNT(DISTINCT ci.PERMID_COMPANY_ID) > 1 ORDER BY external_cnt DESC LIMIT 10;
SELECT c.ID_ZIP FROM FINANCE__ECONOMICS.CYBERSYN_FINANCIAL_CFPB_COMPLAINT c WHERE c.CONSUMER_COMPLAINT_NARRATIVE LIKE '%fraud%' or '%collection%' or '%identity theft%' LIMIT 5;
SELECT c.PRODUCT, COUNT(*) AS event_cnt FROM FINANCE__ECONOMICS.CYBERSYN_FINANCIAL_CFPB_COMPLAINT c WHERE str_to_date(c.DATE_RECEIVED,'%Y-%m-%d') >= '2024-01-01' AND str_to_date(c.DATE_RECEIVED,'%Y-%m-%d') < '2026-01-01' AND c.CONSUMER_COMPLAINT_NARRATIVE LIKE '%fraud%' or '%harassment%' or '%identity theft%' GROUP BY c.PRODUCT ORDER BY event_cnt DESC LIMIT 10;
SELECT c.STATE, c.PRODUCT, COUNT(*) AS event_cnt FROM FINANCE__ECONOMICS.CYBERSYN_FINANCIAL_CFPB_COMPLAINT c GROUP BY c.STATE, c.PRODUCT HAVING COUNT(*) >= 5 ORDER BY event_cnt DESC LIMIT 20;
SELECT COUNT(DISTINCT b.team_batting) AS distinct_entity_cnt FROM IPL.BALL_BY_BALL b;
SELECT pm.team_id, COUNT(*) AS event_cnt FROM IPL.PLAYER_MATCH pm GROUP BY pm.team_id ORDER BY event_cnt DESC LIMIT 1000;
SELECT COUNT(*) AS event_cnt FROM IPL.MATCH m WHERE DATE_FORMAT(STR_TO_DATE(m.match_date, '%Y-%m-%d'), '%Y-%m-%d') >= '2024-01-01' AND DATE_FORMAT(STR_TO_DATE(m.match_date, '%Y-%m-%d'), '%Y-%m-%d') < '2024-01-31';
SELECT er.extra_type, COUNT(*) AS event_cnt FROM IPL.EXTRA_RUNS er GROUP BY er.extra_type ORDER BY event_cnt DESC LIMIT 1000;
SELECT m.win_type, AVG(m.win_margin) AS avg_margin FROM IPL.MATCH m GROUP BY m.win_type ORDER BY avg_margin DESC LIMIT 1000;
SELECT pm.match_id, COUNT(DISTINCT pm.team_id) AS entity_cnt FROM IPL.PLAYER_MATCH pm GROUP BY pm.match_id HAVING COUNT(DISTINCT pm.team_id) > 1 ORDER BY entity_cnt DESC LIMIT 3;
WITH a AS ( SELECT DISTINCT m.match_winner FROM IPL.MATCH m WHERE CAST(m.match_date AS DATETIME) >= '2008-05-01' AND CAST(m.match_date AS DATETIME) < '2008-06-01' ), b AS ( SELECT DISTINCT m.match_winner FROM IPL.MATCH m WHERE CAST(m.match_date AS DATETIME) >= '2008-09-01' AND CAST(m.match_date AS DATETIME) < '2008-10-01' ) SELECT COUNT(*) AS retained_entity_cnt FROM a JOIN b USING (match_winner);
SELECT m.win_type, SUM(CASE WHEN CAST(m.match_date AS DATETIME) >= '2008-05-01' AND CAST(m.match_date AS DATETIME) < '2008-06-01' THEN 1 ELSE 0 END) AS curr_cnt, SUM(CASE WHEN CAST(m.match_date AS DATETIME) >= '2008-09-01' AND CAST(m.match_date AS DATETIME) < '2008-10-01' THEN 1 ELSE 0 END) AS prev_cnt, ( SUM(CASE WHEN CAST(m.match_date AS DATETIME) >= '2008-05-01' AND CAST(m.match_date AS DATETIME) < '2008-06-01' THEN 1 ELSE 0 END) - SUM(CASE WHEN CAST(m.match_date AS DATETIME) >= '2008-09-01' AND CAST(m.match_date AS DATETIME) < '2008-10-01' THEN 1 ELSE 0 END) ) AS delta_cnt FROM IPL.MATCH m GROUP BY m.win_type ORDER BY delta_cnt DESC LIMIT 3;
WITH agg AS ( SELECT m.win_type AS topic, SUM(m.win_margin) AS amt FROM IPL.MATCH m WHERE CAST(m.match_date AS DATETIME) >= '2008-05-01' AND CAST(m.match_date AS DATETIME) < '2008-06-01' GROUP BY m.win_type ), tot AS ( SELECT SUM(amt) AS total_amt FROM agg ) SELECT topic, amt, amt / NULLIF((SELECT total_amt FROM tot), 0) AS amt_share FROM agg ORDER BY amt_share DESC;
SELECT pm.team_id, SUM(CASE WHEN pm.role = 'Captain' THEN 1 ELSE 0 END) AS hit_cnt, COUNT(*) AS total_cnt, SUM(CASE WHEN pm.role = 'Captain' THEN 1 ELSE 0 END) / COUNT(*) AS hit_ratio FROM IPL.PLAYER_MATCH pm GROUP BY pm.team_id HAVING COUNT(*) >= 50 ORDER BY hit_ratio DESC LIMIT 3;
SELECT m.match_id, COUNT(DISTINCT m.season_id) AS external_cnt FROM IPL.MATCH m GROUP BY m.match_id HAVING COUNT(DISTINCT m.season_id) > 1 ORDER BY external_cnt DESC LIMIT 10;
SELECT m.season_id AS id_external FROM IPL.MATCH m WHERE COALESCE(m.outcome_type, '') LIKE '%Result%' or '%Tie%' LIMIT 5;
WITH agg AS ( SELECT pm.role AS topic, t.name AS entity_name, COUNT(*) AS qty FROM IPL.PLAYER_MATCH pm JOIN IPL.TEAM t ON pm.team_id = t.team_id GROUP BY pm.role, t.name ), ranked AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY topic ORDER BY qty DESC, entity_name) AS rn FROM agg ) SELECT topic, entity_name, qty FROM ranked WHERE rn = 1 ORDER BY qty DESC;
SELECT m.win_type, COUNT(*) AS event_cnt FROM IPL.MATCH m WHERE str_to_date(m.match_date,'%Y-%m-%d') >= '2011-01-01' AND str_to_date(m.match_date,'%Y-%m-%d') < '2014-01-01' AND COALESCE(m.outcome_type, '') LIKE '%Result%' GROUP BY m.win_type ORDER BY event_cnt DESC LIMIT 10;
SELECT m.venue AS location, m.win_type AS category_topic, COUNT(*) AS event_cnt FROM IPL.MATCH m GROUP BY m.venue, m.win_type HAVING COUNT(*) >= 10 ORDER BY event_cnt DESC LIMIT 20;
SELECT COUNT(DISTINCT d.OwnerOrganizationId) AS distinct_entity_cnt FROM META_KAGGLE.DATASETS d WHERE d.OwnerOrganizationId IS NOT NULL;
SELECT dt.OwnerUserId, COUNT(*) AS event_cnt FROM META_KAGGLE.DATASETTASKS dt GROUP BY dt.OwnerUserId ORDER BY event_cnt DESC LIMIT 1000;
SELECT COUNT(*) AS event_cnt FROM META_KAGGLE.KERNELVOTES kv WHERE kv.VoteDate >= '2024-01-01 00:00:00' AND kv.VoteDate < '2024-01-31 23:59:59';
SELECT c.RewardType, COUNT(*) AS event_cnt FROM META_KAGGLE.COMPETITIONS c GROUP BY c.RewardType ORDER BY event_cnt DESC LIMIT 1000;
SELECT ea.State, SUM(ea.Reward) AS total_amount FROM META_KAGGLE.EPISODEAGENTS ea GROUP BY ea.State ORDER BY total_amount DESC LIMIT 1000;
SELECT ct.CompetitionId, COUNT(DISTINCT ct.TagId) AS entity_cnt FROM META_KAGGLE.COMPETITIONTAGS ct GROUP BY ct.CompetitionId HAVING COUNT(DISTINCT ct.TagId) > 1 ORDER BY entity_cnt DESC LIMIT 3;
WITH a AS ( SELECT DISTINCT k.AuthorUserId FROM META_KAGGLE.KERNELS k WHERE k.MadePublicDate >= '2022-07-01' AND k.MadePublicDate < '2022-09-01' ), b AS ( SELECT DISTINCT k.AuthorUserId FROM META_KAGGLE.KERNELS k WHERE k.MadePublicDate >= '2023-07-01' AND k.MadePublicDate < '2023-09-01' ) SELECT COUNT(*) AS retained_entity_cnt FROM a JOIN b USING (AuthorUserId);
WITH agg AS ( SELECT ea.State AS topic, SUM(ea.Reward) AS amt FROM META_KAGGLE.EPISODEAGENTS ea JOIN META_KAGGLE.EPISODES e ON ea.EpisodeId = e.Id WHERE e.EndTime >= '2020-09-01' AND e.EndTime < '2020-09-30' GROUP BY ea.State ), tot AS ( SELECT SUM(amt) AS total_amt FROM agg ) SELECT topic, amt, amt / NULLIF((SELECT total_amt FROM tot), 0) AS amt_share FROM agg ORDER BY amt_share DESC;
WITH daily AS ( SELECT DATE( kv.VoteDate) AS d, COUNT(*) AS cnt FROM META_KAGGLE.KERNELVOTES kv WHERE CAST(kv.VoteDate AS DATETIME) >= '2019-07-01' AND CAST(kv.VoteDate AS DATETIME) < '2019-07-08' GROUP BY d ), ma AS ( SELECT d, cnt, AVG(cnt) OVER (ORDER BY d ROWS BETWEEN 7 PRECEDING AND 1 PRECEDING) AS prev_7d_avg FROM daily ) SELECT d, cnt, prev_7d_avg FROM ma WHERE prev_7d_avg IS NOT NULL AND cnt > prev_7d_avg ORDER BY (cnt - prev_7d_avg) DESC;
SELECT ea.EpisodeId, SUM(CASE WHEN ea.State = '2' THEN 1 ELSE 0 END) AS hit_cnt, COUNT(*) AS total_cnt, SUM(CASE WHEN ea.State = '2' THEN 1 ELSE 0 END) / COUNT(*) AS hit_ratio FROM META_KAGGLE.EPISODEAGENTS ea GROUP BY ea.EpisodeId HAVING COUNT(*) >= 1 ORDER BY hit_ratio DESC LIMIT 3;
SELECT d.Id, COUNT(DISTINCT d.CurrentDatasetVersionId) AS external_cnt FROM META_KAGGLE.DATASETS d GROUP BY d.Id HAVING COUNT(DISTINCT d.CurrentDatasetVersionId) > 1 ORDER BY external_cnt DESC LIMIT 10;
SELECT fm.ForumTopicId AS id_external FROM META_KAGGLE.FORUMMESSAGES fm WHERE COALESCE(fm.RawMarkdown, '') LIKE '%bug%' or '%submission%' or '%GPU%' LIMIT 5;
WITH agg AS ( SELECT c.RewardType AS topic, c.EvaluationAlgorithmName AS entity_name, COUNT(*) AS qty FROM META_KAGGLE.COMPETITIONS c WHERE c.EvaluationAlgorithmName IS NOT NULL GROUP BY c.RewardType, c.EvaluationAlgorithmName ), ranked AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY topic ORDER BY qty DESC, entity_name) AS rn FROM agg ) SELECT topic, entity_name, qty FROM ranked WHERE rn = 1 ORDER BY qty DESC;
SELECT fm.ForumTopicId AS category_topic, COUNT(*) AS event_cnt FROM META_KAGGLE.FORUMMESSAGES fm WHERE str_to_date(fm.PostDate, '%m/%d/%Y %H:%i:%s') >= '2021-01-01' AND str_to_date(fm.PostDate, '%m/%d/%Y %H:%i:%s') < '2024-01-01' AND COALESCE(fm.RawMarkdown, '') LIKE '%submission error%' or '%GPU%' or '%dataset link%' GROUP BY fm.ForumTopicId ORDER BY event_cnt DESC LIMIT 10;
SELECT COUNT(DISTINCT a.state_number) AS distinct_entity_cnt FROM NHTSA_TRAFFIC_FATALITIES.ACCIDENT_2016 a;
SELECT d.vehicle_number, COUNT(*) AS event_cnt FROM NHTSA_TRAFFIC_FATALITIES.DAMAGE_2016 d GROUP BY d.vehicle_number ORDER BY event_cnt DESC LIMIT 1000;
SELECT COUNT(*) AS event_cnt FROM NHTSA_TRAFFIC_FATALITIES.ACCIDENT_2016 a WHERE FROM_UNIXTIME(a.timestamp_of_crash / 1000000) >= '2024-01-01 00:00:00' AND FROM_UNIXTIME(a.timestamp_of_crash / 1000000) < '2024-01-31 23:59:59';
SELECT v.driver_drinking, COUNT(*) AS event_cnt FROM NHTSA_TRAFFIC_FATALITIES.VEHICLE_2016 v GROUP BY v.driver_drinking ORDER BY event_cnt DESC LIMIT 1000;
SELECT a.state_name, SUM(a.number_of_fatalities) AS total_quantity FROM NHTSA_TRAFFIC_FATALITIES.ACCIDENT_2016 a GROUP BY a.state_name ORDER BY total_quantity DESC LIMIT 1000;
SELECT d.consecutive_number, COUNT(DISTINCT d.vehicle_number) AS entity_cnt FROM NHTSA_TRAFFIC_FATALITIES.DAMAGE_2016 d GROUP BY d.consecutive_number HAVING COUNT(DISTINCT d.vehicle_number) > 1 ORDER BY entity_cnt DESC LIMIT 3;
WITH a_win AS ( SELECT DISTINCT a.state_number FROM NHTSA_TRAFFIC_FATALITIES.ACCIDENT_2016 a WHERE FROM_UNIXTIME(a.timestamp_of_crash / 1000000) >= '2016-01-01 00:00:00' AND FROM_UNIXTIME(a.timestamp_of_crash / 1000000) < '2016-04-01 00:00:00' ), b_win AS ( SELECT DISTINCT a.state_number FROM NHTSA_TRAFFIC_FATALITIES.ACCIDENT_2016 a WHERE FROM_UNIXTIME(a.timestamp_of_crash / 1000000) >= '2016-10-01 00:00:00' AND FROM_UNIXTIME(a.timestamp_of_crash / 1000000) < '2017-01-01 00:00:00' ) SELECT COUNT(*) AS retained_entity_cnt FROM a_win JOIN b_win USING (state_number);
SELECT a.light_condition_name, SUM(CASE WHEN FROM_UNIXTIME(a.timestamp_of_crash / 1000000) >= '2016-01-01 00:00:00' AND FROM_UNIXTIME(a.timestamp_of_crash / 1000000) < '2016-04-01 00:00:00' THEN 1 ELSE 0 END) AS curr_cnt, SUM(CASE WHEN FROM_UNIXTIME(a.timestamp_of_crash / 1000000) >= '2016-10-01 00:00:00' AND FROM_UNIXTIME(a.timestamp_of_crash / 1000000) < '2017-01-01 00:00:00' THEN 1 ELSE 0 END) AS prev_cnt, ( SUM(CASE WHEN FROM_UNIXTIME(a.timestamp_of_crash / 1000000) >= '2016-01-01 00:00:00' AND FROM_UNIXTIME(a.timestamp_of_crash / 1000000) < '2016-04-01 00:00:00' THEN 1 ELSE 0 END) - SUM(CASE WHEN FROM_UNIXTIME(a.timestamp_of_crash / 1000000) >= '2016-10-01 00:00:00' AND FROM_UNIXTIME(a.timestamp_of_crash / 1000000) < '2017-01-01 00:00:00' THEN 1 ELSE 0 END) ) AS delta_cnt FROM NHTSA_TRAFFIC_FATALITIES.ACCIDENT_2016 a GROUP BY a.light_condition_name ORDER BY delta_cnt DESC LIMIT 3;
WITH agg AS ( SELECT a.state_name AS topic, SUM(a.number_of_fatalities) AS qty FROM NHTSA_TRAFFIC_FATALITIES.ACCIDENT_2016 a WHERE FROM_UNIXTIME(a.timestamp_of_crash / 1000000) >= '2016-01-01 00:00:00' AND FROM_UNIXTIME(a.timestamp_of_crash / 1000000) < '2016-04-01 00:00:00' GROUP BY a.state_name ), tot AS ( SELECT SUM(qty) AS total_qty FROM agg ) SELECT topic, qty, qty / NULLIF((SELECT total_qty FROM tot), 0) AS qty_share FROM agg ORDER BY qty_share DESC;
WITH daily AS ( SELECT DATE( FROM_UNIXTIME(a.timestamp_of_crash / 1000000)) AS d, COUNT(*) AS cnt FROM NHTSA_TRAFFIC_FATALITIES.ACCIDENT_2016 a WHERE FROM_UNIXTIME(a.timestamp_of_crash / 1000000) >= '2016-01-01 00:00:00' AND FROM_UNIXTIME(a.timestamp_of_crash / 1000000) < '2016-04-01 00:00:00' GROUP BY d ), ma AS ( SELECT d, cnt, AVG(cnt) OVER (ORDER BY d ROWS BETWEEN 7 PRECEDING AND 1 PRECEDING) AS prev_7d_avg FROM daily ) SELECT d, cnt, prev_7d_avg FROM ma WHERE prev_7d_avg IS NOT NULL AND cnt > prev_7d_avg ORDER BY (cnt - prev_7d_avg) DESC LIMIT 3;
SELECT p.person_number, COUNT(DISTINCT p.consecutive_number) AS external_cnt FROM NHTSA_TRAFFIC_FATALITIES.PERSON_2016 p GROUP BY p.person_number HAVING COUNT(DISTINCT p.consecutive_number) > 1 ORDER BY external_cnt DESC LIMIT 10;
SELECT a.consecutive_number AS id_external FROM NHTSA_TRAFFIC_FATALITIES.ACCIDENT_2016 a WHERE COALESCE(a.related_factors_crash_level_1_name, '') LIKE '%distraction%' or '%weather%' or '%speeding%' LIMIT 5;
WITH agg AS ( SELECT p.injury_severity_name AS topic, p.person_type_name AS entity_name, COUNT(*) AS qty FROM NHTSA_TRAFFIC_FATALITIES.PERSON_2016 p GROUP BY p.injury_severity_name, p.person_type_name ), ranked AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY topic ORDER BY qty DESC, entity_name) AS rn FROM agg ) SELECT topic, entity_name, qty FROM ranked WHERE rn = 1 ORDER BY qty DESC;
SELECT a.light_condition_name, COUNT(*) AS event_cnt FROM NHTSA_TRAFFIC_FATALITIES.ACCIDENT_2016 a WHERE FROM_UNIXTIME(a.timestamp_of_crash/ 1000000) >= '2016-01-01' AND FROM_UNIXTIME(a.timestamp_of_crash/ 1000000) < '2016-03-01' AND COALESCE(a.related_factors_crash_level_1_name, '') LIKE '%Crash%' GROUP BY a.light_condition_name ORDER BY event_cnt DESC LIMIT 10;
SELECT a.state_name AS location, a.light_condition_name AS category_topic, COUNT(*) AS event_cnt FROM NHTSA_TRAFFIC_FATALITIES.ACCIDENT_2016 a GROUP BY a.state_name, a.light_condition_name HAVING COUNT(*) >= 10 ORDER BY event_cnt DESC LIMIT 20;
SELECT COUNT(DISTINCT t.state_code) AS distinct_entity_cnt FROM OPENAQ.EPA_HISTORICAL_AIR_QUALITY_PM25_FRM_DAILY_SUMMARY t WHERE t.state_code IS NOT NULL;
SELECT t.county_code, COUNT(*) AS event_cnt FROM OPENAQ.EPA_HISTORICAL_AIR_QUALITY_PM25_FRM_DAILY_SUMMARY t WHERE t.county_code IS NOT NULL AND t.site_num IS NOT NULL GROUP BY t.county_code ORDER BY event_cnt DESC LIMIT 1000;
SELECT COUNT(*) AS event_cnt FROM OPENAQ.OPENAQ_GLOBAL_AIR_QUALITY t WHERE FROM_UNIXTIME(t.timestamp / 1000000) >= '2024-01-01 00:00:00' AND FROM_UNIXTIME(t.timestamp / 1000000) < '2024-01-31 23:59:59';
SELECT t.pollutant, COUNT(*) AS event_cnt FROM OPENAQ.OPENAQ_GLOBAL_AIR_QUALITY t WHERE t.pollutant IS NOT NULL GROUP BY t.pollutant ORDER BY event_cnt DESC LIMIT 1000;
SELECT t.pollutant, AVG(t.value) AS avg_value FROM OPENAQ.OPENAQ_GLOBAL_AIR_QUALITY t WHERE t.pollutant IS NOT NULL AND t.value IS NOT NULL GROUP BY t.pollutant ORDER BY avg_value DESC LIMIT 1000;
SELECT t.site_num, COUNT(DISTINCT t.method_code) AS entity_cnt FROM OPENAQ.EPA_HISTORICAL_AIR_QUALITY_PM10_DAILY_SUMMARY t WHERE t.site_num IS NOT NULL GROUP BY t.site_num HAVING COUNT(DISTINCT t.method_code) > 1 ORDER BY entity_cnt DESC LIMIT 3;
WITH a AS ( SELECT DISTINCT t.location FROM OPENAQ.openaq_global_air_quality t WHERE t.location IS NOT NULL AND FROM_UNIXTIME(t.timestamp / 1000000) >= '2022-05-04 09:00:00' AND FROM_UNIXTIME(t.timestamp / 1000000) < '2022-05-04 11:00:00' ), b AS ( SELECT DISTINCT t.location FROM OPENAQ.openaq_global_air_quality t WHERE t.location IS NOT NULL AND FROM_UNIXTIME(t.timestamp / 1000000) >= '2022-05-04 13:00:00' AND FROM_UNIXTIME(t.timestamp / 1000000) < '2022-05-04 15:00:00' ) SELECT COUNT(*) AS retained_entity_cnt FROM a JOIN b USING (location);
SELECT t.pollutant, SUM(CASE WHEN FROM_UNIXTIME(t.timestamp / 1000000) >= '2022-05-04 09:00:00' AND FROM_UNIXTIME(t.timestamp / 1000000) < '2022-05-04 11:00:00' THEN 1 ELSE 0 END) AS curr_cnt, SUM(CASE WHEN FROM_UNIXTIME(t.timestamp / 1000000) >= '2022-05-04 13:00:00' AND FROM_UNIXTIME(t.timestamp / 1000000) < '2022-05-04 15:00:00' THEN 1 ELSE 0 END) AS prev_cnt, ( SUM(CASE WHEN FROM_UNIXTIME(t.timestamp / 1000000) >= '2022-05-04 09:00:00' AND FROM_UNIXTIME(t.timestamp / 1000000) < '2022-05-04 11:00:00' THEN 1 ELSE 0 END) - SUM(CASE WHEN FROM_UNIXTIME(t.timestamp / 1000000) >= '2022-05-04 13:00:00' AND FROM_UNIXTIME(t.timestamp / 1000000) < '2022-05-04 15:00:00' THEN 1 ELSE 0 END) ) AS delta_cnt FROM OPENAQ.openaq_global_air_quality t WHERE t.pollutant IS NOT NULL GROUP BY t.pollutant ORDER BY delta_cnt DESC LIMIT 3;
WITH agg AS ( SELECT t.pollutant AS topic, AVG(t.value) AS amt FROM OPENAQ.openaq_global_air_quality t WHERE FROM_UNIXTIME(t.timestamp / 1000000) >= '2022-05-04 09:00:00' AND FROM_UNIXTIME(t.timestamp / 1000000) < '2022-05-04 11:00:00' AND t.pollutant IS NOT NULL AND t.value IS NOT NULL GROUP BY t.pollutant ), tot AS ( SELECT SUM(amt) AS total_amt FROM agg ) SELECT topic, amt, amt / NULLIF((SELECT total_amt FROM tot), 0) AS amt_share FROM agg ORDER BY amt_share DESC;
WITH daily AS ( SELECT DATE( FROM_UNIXTIME(t.timestamp / 1000000)) AS d, COUNT(*) AS cnt FROM OPENAQ.openaq_global_air_quality t WHERE FROM_UNIXTIME(t.timestamp / 1000000) >= '2022-05-03 00:00:00' AND FROM_UNIXTIME(t.timestamp / 1000000) < '2022-05-05 00:00:00' GROUP BY d ), ma AS ( SELECT d, cnt, AVG(cnt) OVER (ORDER BY d ROWS BETWEEN 7 PRECEDING AND 1 PRECEDING) AS prev_7d_avg FROM daily ) SELECT d, cnt, prev_7d_avg FROM ma WHERE prev_7d_avg IS NOT NULL AND cnt > prev_7d_avg ORDER BY (cnt - prev_7d_avg) DESC;
SELECT t.parameter_code, COUNT(DISTINCT t.parameter_name) AS external_cnt FROM OPENAQ.EPA_HISTORICAL_AIR_QUALITY_AIR_QUALITY_ANNUAL_SUMMARY t GROUP BY t.parameter_code HAVING COUNT(DISTINCT t.parameter_name) > 1 ORDER BY external_cnt DESC LIMIT 10;
SELECT t.site_num AS id_external FROM OPENAQ.EPA_HISTORICAL_AIR_QUALITY_PM25_NONFRM_DAILY_SUMMARY t WHERE COALESCE(t.pollutant_standard, '') LIKE '%标准版本%' or '%8-hour%' or '%annual%' LIMIT 5;
WITH agg AS ( SELECT t.state_name AS topic, t.local_site_name AS entity_name, COUNT(*) AS qty FROM OPENAQ.EPA_HISTORICAL_AIR_QUALITY_AIR_QUALITY_ANNUAL_SUMMARY t WHERE t.state_name IS NOT NULL AND t.local_site_name IS NOT NULL GROUP BY t.state_name, t.local_site_name ), ranked AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY topic ORDER BY qty DESC, entity_name) AS rn FROM agg ) SELECT topic, entity_name, qty FROM ranked WHERE rn = 1 ORDER BY qty DESC;
SELECT t.parameter_name AS category_topic, COUNT(*) AS event_cnt FROM OPENAQ.EPA_HISTORICAL_AIR_QUALITY_PM10_DAILY_SUMMARY t WHERE str_to_date(t.date_local, '%Y-%m-%d') >= '1996-05-01' AND str_to_date(t.date_local, '%Y-%m-%d') < '1996-07-01' AND COALESCE(t.pollutant_standard, '') LIKE '%PM10%' GROUP BY t.parameter_name ORDER BY event_cnt DESC LIMIT 10;
SELECT t.address AS location, t.parameter_name AS category_topic, COUNT(*) AS event_cnt FROM OPENAQ.EPA_HISTORICAL_AIR_QUALITY_PM25_NONFRM_DAILY_SUMMARY t WHERE t.address IS NOT NULL AND t.parameter_name IS NOT NULL GROUP BY t.address, t.parameter_name HAVING COUNT(*) >= 5 ORDER BY event_cnt DESC LIMIT 20;
SELECT COUNT(DISTINCT t.start_station_id) AS distinct_entity_cnt FROM SAN_FRANCISCO_PLUS.SAN_FRANCISCO_BIKESHARE_BIKESHARE_TRIPS t WHERE t.start_station_id IS NOT NULL;
SELECT t.unit_id, COUNT(*) AS event_cnt FROM SAN_FRANCISCO_PLUS.SAN_FRANCISCO_SFFD_SERVICE_CALLS_SFFD_SERVICE_CALLS t WHERE t.unit_id IS NOT NULL AND t.call_number IS NOT NULL GROUP BY t.unit_id ORDER BY event_cnt DESC LIMIT 1000;
SELECT COUNT(*) AS event_cnt FROM SAN_FRANCISCO_PLUS.SAN_FRANCISCO_SFPD_INCIDENTS_SFPD_INCIDENTS t WHERE FROM_UNIXTIME(t.timestamp / 1000000) >= '2024-01-01 00:00:00' AND FROM_UNIXTIME(t.timestamp / 1000000) < '2024-01-31 23:59:59';
SELECT t.category, COUNT(*) AS event_cnt FROM SAN_FRANCISCO_PLUS.SAN_FRANCISCO_311__311_SERVICE_REQUESTS t WHERE t.category IS NOT NULL GROUP BY t.category ORDER BY event_cnt DESC LIMIT 1000;
SELECT t.subscriber_type, AVG(t.duration_sec) AS avg_duration_sec FROM SAN_FRANCISCO_PLUS.SAN_FRANCISCO_BIKESHARE_BIKESHARE_TRIPS t WHERE t.subscriber_type IS NOT NULL AND t.duration_sec IS NOT NULL GROUP BY t.subscriber_type ORDER BY avg_duration_sec DESC LIMIT 1000;
SELECT t.call_number, COUNT(DISTINCT t.unit_id) AS entity_cnt FROM SAN_FRANCISCO_PLUS.san_francisco_sffd_service_calls_sffd_service_calls t WHERE t.call_number IS NOT NULL GROUP BY t.call_number HAVING COUNT(DISTINCT t.unit_id) > 1 ORDER BY entity_cnt DESC LIMIT 3;
WITH a AS ( SELECT DISTINCT t.start_station_id FROM SAN_FRANCISCO_PLUS.san_francisco_bikeshare_bikeshare_trips t WHERE t.start_station_id IS NOT NULL AND FROM_UNIXTIME(t.start_date / 1000000) >= '2018-02-15 14:00:00' AND FROM_UNIXTIME(t.start_date / 1000000) < '2018-02-15 15:00:00' ), b AS ( SELECT DISTINCT t.start_station_id FROM SAN_FRANCISCO_PLUS.san_francisco_bikeshare_bikeshare_trips t WHERE t.start_station_id IS NOT NULL AND FROM_UNIXTIME(t.start_date / 1000000) >= '2018-02-15 16:00:00' AND FROM_UNIXTIME(t.start_date / 1000000) < '2018-02-15 17:00:00' ) SELECT COUNT(*) AS retained_entity_cnt FROM a JOIN b USING (start_station_id);
WITH agg AS ( SELECT t.subscriber_type AS topic, SUM(t.duration_sec) AS amt FROM SAN_FRANCISCO_PLUS.san_francisco_bikeshare_bikeshare_trips t WHERE FROM_UNIXTIME(t.start_date / 1000000) >= '2018-02-01 00:00:00' AND FROM_UNIXTIME(t.start_date / 1000000) < '2018-04-01 00:00:00' AND t.subscriber_type IS NOT NULL GROUP BY t.subscriber_type ), tot AS ( SELECT SUM(amt) AS total_amt FROM agg ) SELECT topic, amt, amt / NULLIF((SELECT total_amt FROM tot), 0) AS amt_share FROM agg ORDER BY amt_share DESC;
WITH daily AS ( SELECT DATE( t.call_date) AS d, COUNT(*) AS cnt FROM SAN_FRANCISCO_PLUS.san_francisco_sffd_service_calls_sffd_service_calls t WHERE CAST(t.call_date AS DATETIME) >= '2011-10-10 00:00:00' AND CAST(t.call_date AS DATETIME) < '2011-10-18 00:00:00' GROUP BY d ), ma AS ( SELECT d, cnt, AVG(cnt) OVER (ORDER BY d ROWS BETWEEN 7 PRECEDING AND 1 PRECEDING) AS prev_7d_avg FROM daily ) SELECT d, cnt, prev_7d_avg FROM ma WHERE prev_7d_avg IS NOT NULL AND cnt > prev_7d_avg ORDER BY (cnt - prev_7d_avg) DESC;
SELECT t.unique_key AS rel_entity, SUM(CASE WHEN t.status = 'Closed' THEN 1 ELSE 0 END) AS hit_cnt, COUNT(*) AS total_cnt, SUM(CASE WHEN t.status = 'Closed' THEN 1 ELSE 0 END) / COUNT(*) AS hit_ratio FROM SAN_FRANCISCO_PLUS.SAN_FRANCISCO_311__311_SERVICE_REQUESTS t GROUP BY t.unique_key HAVING COUNT(*) >= 1 ORDER BY hit_ratio DESC LIMIT 3;
SELECT t.station_id, COUNT(DISTINCT t.external_id) AS external_cnt FROM SAN_FRANCISCO_PLUS.SAN_FRANCISCO_BIKESHARE_BIKESHARE_STATION_INFO t GROUP BY t.station_id HAVING COUNT(DISTINCT t.external_id) > 1 ORDER BY external_cnt DESC LIMIT 10;
SELECT t.unique_key AS id_external FROM SAN_FRANCISCO_PLUS.SAN_FRANCISCO_311__311_SERVICE_REQUESTS t WHERE COALESCE(t.status_notes, '') LIKE '%transferred%' or '%duplicate%' or '%referred%' LIMIT 5;
WITH agg AS ( SELECT t.category AS topic, t.agency_name AS entity_name, COUNT(*) AS qty FROM SAN_FRANCISCO_PLUS.SAN_FRANCISCO_311__311_SERVICE_REQUESTS t WHERE t.category IS NOT NULL AND t.agency_name IS NOT NULL GROUP BY t.category, t.agency_name ), ranked AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY topic ORDER BY qty DESC, entity_name) AS rn FROM agg ) SELECT topic, entity_name, qty FROM ranked WHERE rn = 1 ORDER BY qty DESC;
SELECT t.category, COUNT(*) AS event_cnt FROM SAN_FRANCISCO_PLUS.SAN_FRANCISCO_311__311_SERVICE_REQUESTS t WHERE FROM_UNIXTIME(created_date / 1000000) >= '2020-01-01' AND FROM_UNIXTIME(created_date / 1000000) < '2023-01-01' AND COALESCE(t.status_notes, '') LIKE '%Case Transferred%' GROUP BY t.category ORDER BY event_cnt DESC LIMIT 10;
SELECT t.address AS location, t.category AS category_topic, COUNT(*) AS event_cnt FROM SAN_FRANCISCO_PLUS.SAN_FRANCISCO_SFPD_INCIDENTS_SFPD_INCIDENTS t WHERE t.address IS NOT NULL AND t.category IS NOT NULL GROUP BY t.address, t.category HAVING COUNT(*) >= 10 ORDER BY event_cnt DESC LIMIT 20;
SELECT COUNT(DISTINCT ii.product_distribution_center_id) AS distinct_entity_cnt FROM THELOOK_ECOMMERCE.INVENTORY_ITEMS ii WHERE ii.product_distribution_center_id IS NOT NULL;
SELECT ii.product_distribution_center_id, COUNT(*) AS event_cnt FROM THELOOK_ECOMMERCE.INVENTORY_ITEMS ii WHERE ii.product_distribution_center_id IS NOT NULL AND ii.product_sku IS NOT NULL GROUP BY ii.product_distribution_center_id ORDER BY event_cnt DESC LIMIT 1000;
SELECT COUNT(*) AS event_cnt FROM THELOOK_ECOMMERCE.INVENTORY_ITEMS ii WHERE FROM_UNIXTIME(ii.sold_at / 1000000) >= '2024-01-01 00:00:00' AND FROM_UNIXTIME(ii.sold_at / 1000000) < '2024-01-31 23:59:59';
SELECT ii.product_category, COUNT(*) AS event_cnt FROM THELOOK_ECOMMERCE.INVENTORY_ITEMS ii WHERE ii.product_category IS NOT NULL GROUP BY ii.product_category ORDER BY event_cnt DESC LIMIT 1000;
SELECT ii.product_department, SUM(ii.product_retail_price) AS total_amount FROM THELOOK_ECOMMERCE.INVENTORY_ITEMS ii WHERE ii.product_department IS NOT NULL AND ii.product_retail_price IS NOT NULL GROUP BY ii.product_department ORDER BY total_amount DESC LIMIT 1000;
SELECT p.sku, COUNT(DISTINCT p.distribution_center_id) AS entity_cnt FROM THELOOK_ECOMMERCE.PRODUCTS p WHERE p.sku IS NOT NULL GROUP BY p.sku HAVING COUNT(DISTINCT p.distribution_center_id) > 1 ORDER BY entity_cnt DESC LIMIT 3;
WITH a AS ( SELECT DISTINCT ii.product_distribution_center_id FROM THELOOK_ECOMMERCE.INVENTORY_ITEMS ii WHERE ii.product_distribution_center_id IS NOT NULL AND FROM_UNIXTIME(ii.sold_at / 1000000) >= '2023-01-14 10:00:00' AND FROM_UNIXTIME(ii.sold_at / 1000000) < '2023-01-14 11:00:00' ), b AS ( SELECT DISTINCT ii.product_distribution_center_id FROM THELOOK_ECOMMERCE.INVENTORY_ITEMS ii WHERE ii.product_distribution_center_id IS NOT NULL AND FROM_UNIXTIME(ii.sold_at / 1000000) >= '2023-01-14 13:00:00' AND FROM_UNIXTIME(ii.sold_at / 1000000) < '2023-01-14 14:00:00' ) SELECT COUNT(*) AS retained_entity_cnt FROM a JOIN b USING (product_distribution_center_id);
SELECT ii.product_category, SUM(CASE WHEN FROM_UNIXTIME(ii.sold_at / 1000000) >= '2023-01-14 10:00:00' AND FROM_UNIXTIME(ii.sold_at / 1000000) < '2023-01-14 11:00:00' THEN 1 ELSE 0 END) AS curr_cnt, SUM(CASE WHEN FROM_UNIXTIME(ii.sold_at / 1000000) >= '2023-01-14 13:00:00' AND FROM_UNIXTIME(ii.sold_at / 1000000) < '2023-01-14 14:00:00' THEN 1 ELSE 0 END) AS prev_cnt, ( SUM(CASE WHEN FROM_UNIXTIME(ii.sold_at / 1000000) >= '2023-01-14 10:00:00' AND FROM_UNIXTIME(ii.sold_at / 1000000) < '2023-01-14 11:00:00' THEN 1 ELSE 0 END) - SUM(CASE WHEN FROM_UNIXTIME(ii.sold_at / 1000000) >= '2023-01-14 13:00:00' AND FROM_UNIXTIME(ii.sold_at / 1000000) < '2023-01-14 14:00:00' THEN 1 ELSE 0 END) ) AS delta_cnt FROM THELOOK_ECOMMERCE.INVENTORY_ITEMS ii WHERE ii.product_category IS NOT NULL GROUP BY ii.product_category ORDER BY delta_cnt DESC LIMIT 3;
WITH agg AS ( SELECT ii.product_department AS topic, SUM(ii.product_retail_price) AS amt FROM THELOOK_ECOMMERCE.INVENTORY_ITEMS ii WHERE FROM_UNIXTIME(ii.sold_at / 1000000) >= '2023-02-01 00:00:00' AND FROM_UNIXTIME(ii.sold_at / 1000000) < '2023-04-01 00:00:00' AND ii.product_department IS NOT NULL GROUP BY ii.product_department ), tot AS ( SELECT SUM(amt) AS total_amt FROM agg ) SELECT topic, amt, amt / NULLIF((SELECT total_amt FROM tot), 0) AS amt_share FROM agg ORDER BY amt_share DESC;
WITH daily AS ( SELECT DATE( FROM_UNIXTIME(ii.sold_at / 1000000)) AS d, COUNT(*) AS cnt FROM THELOOK_ECOMMERCE.INVENTORY_ITEMS ii WHERE FROM_UNIXTIME(ii.sold_at / 1000000) >= '2023-07-10 00:00:00' AND FROM_UNIXTIME(ii.sold_at / 1000000) < '2023-07-24 00:00:00' GROUP BY d ), ma AS ( SELECT d, cnt, AVG(cnt) OVER (ORDER BY d ROWS BETWEEN 7 PRECEDING AND 1 PRECEDING) AS prev_7d_avg FROM daily ) SELECT d, cnt, prev_7d_avg FROM ma WHERE prev_7d_avg IS NOT NULL AND cnt > prev_7d_avg ORDER BY (cnt - prev_7d_avg) DESC;
SELECT o.user_id, SUM(CASE WHEN o.status = 'Cancelled' THEN 1 ELSE 0 END) AS hit_cnt, COUNT(*) AS total_cnt, SUM(CASE WHEN o.status = 'Cancelled' THEN 1 ELSE 0 END) / COUNT(*) AS hit_ratio FROM THELOOK_ECOMMERCE.ORDERS o WHERE o.user_id IS NOT NULL GROUP BY o.user_id HAVING COUNT(*) >= 10 ORDER BY hit_ratio DESC LIMIT 3;
SELECT p.id, COUNT(DISTINCT p.sku) AS external_cnt FROM THELOOK_ECOMMERCE.PRODUCTS p GROUP BY p.id HAVING COUNT(DISTINCT p.sku) > 1 ORDER BY external_cnt DESC LIMIT 10;
WITH agg AS ( SELECT ii.product_category AS topic, ii.product_brand AS entity_name, SUM(ii.product_retail_price) AS amt FROM THELOOK_ECOMMERCE.INVENTORY_ITEMS ii WHERE ii.product_category IS NOT NULL AND ii.product_brand IS NOT NULL AND ii.product_retail_price IS NOT NULL GROUP BY ii.product_category, ii.product_brand ), ranked AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY topic ORDER BY amt DESC, entity_name) AS rn FROM agg ) SELECT topic, entity_name, amt FROM ranked WHERE rn = 1 ORDER BY amt DESC;
SELECT dc.name AS location, ii.product_department AS category_topic, COUNT(*) AS event_cnt FROM THELOOK_ECOMMERCE.INVENTORY_ITEMS ii JOIN THELOOK_ECOMMERCE.DISTRIBUTION_CENTERS dc ON ii.product_distribution_center_id = dc.id WHERE dc.name IS NOT NULL AND ii.product_department IS NOT NULL GROUP BY dc.name, ii.product_department HAVING COUNT(*) >= 5 ORDER BY event_cnt DESC LIMIT 20;
SELECT COUNT(DISTINCT o.CustomerID) AS distinct_entity_cnt FROM WIDE_WORLD_IMPORTERS.SALES_ORDERS o WHERE o.CustomerID IS NOT NULL;
SELECT o.CustomerID, COUNT(*) AS event_cnt FROM WIDE_WORLD_IMPORTERS.SALES_ORDERS o WHERE o.CustomerID IS NOT NULL AND o.CustomerPurchaseOrderNumber IS NOT NULL GROUP BY o.CustomerID ORDER BY event_cnt DESC LIMIT 1000;
SELECT COUNT(*) AS event_cnt FROM WIDE_WORLD_IMPORTERS.SALES_ORDERS o WHERE o.OrderDate >= '2024-01-01 00:00:00' AND o.OrderDate < '2024-01-31 23:59:59';
SELECT t.TransactionTypeID, COUNT(*) AS event_cnt FROM WIDE_WORLD_IMPORTERS.PURCHASING_SUPPLIERTRANSACTIONS t WHERE t.TransactionTypeID IS NOT NULL GROUP BY t.TransactionTypeID ORDER BY event_cnt DESC LIMIT 1000;
SELECT t.TransactionTypeID, SUM(t.TransactionAmount) AS total_amount FROM WIDE_WORLD_IMPORTERS.SALES_CUSTOMERTRANSACTIONS t WHERE t.TransactionTypeID IS NOT NULL AND t.TransactionAmount IS NOT NULL GROUP BY t.TransactionTypeID ORDER BY total_amount DESC LIMIT 1000;
SELECT o.CustomerPurchaseOrderNumber, COUNT(DISTINCT o.CustomerID) AS entity_cnt FROM WIDE_WORLD_IMPORTERS.SALES_ORDERS o WHERE o.CustomerPurchaseOrderNumber IS NOT NULL GROUP BY o.CustomerPurchaseOrderNumber HAVING COUNT(DISTINCT o.CustomerID) > 1 ORDER BY entity_cnt DESC LIMIT 3;
WITH a AS ( SELECT DISTINCT o.CustomerID FROM WIDE_WORLD_IMPORTERS.SALES_ORDERS o WHERE o.CustomerID IS NOT NULL AND o.OrderDate >= '2015-09-10' AND o.OrderDate < '2015-09-16' ), b AS ( SELECT DISTINCT o.CustomerID FROM WIDE_WORLD_IMPORTERS.SALES_ORDERS o WHERE o.CustomerID IS NOT NULL AND o.OrderDate >= '2015-09-20' AND o.OrderDate < '2015-09-26' ) SELECT COUNT(*) AS retained_entity_cnt FROM a JOIN b USING (CustomerID);
SELECT t.TransactionTypeID, SUM(CASE WHEN t.TransactionDate >= '2015-09-10' AND t.TransactionDate < '2015-09-16' THEN 1 ELSE 0 END) AS curr_cnt, SUM(CASE WHEN t.TransactionDate >= '2015-09-20' AND t.TransactionDate < '2015-09-26' THEN 1 ELSE 0 END) AS prev_cnt, ( SUM(CASE WHEN t.TransactionDate >= '2015-09-10' AND t.TransactionDate < '2015-09-16' THEN 1 ELSE 0 END) - SUM(CASE WHEN t.TransactionDate >= '2015-09-20' AND t.TransactionDate < '2015-09-26' THEN 1 ELSE 0 END) ) AS delta_cnt FROM WIDE_WORLD_IMPORTERS.SALES_CUSTOMERTRANSACTIONS t WHERE t.TransactionTypeID IS NOT NULL GROUP BY t.TransactionTypeID ORDER BY delta_cnt DESC LIMIT 3;
WITH agg AS ( SELECT t.TransactionTypeID AS topic, SUM(t.TransactionAmount) AS amt FROM WIDE_WORLD_IMPORTERS.SALES_CUSTOMERTRANSACTIONS t WHERE CAST(t.TransactionDate AS DATETIME) >= '2013-02-01' AND CAST(t.TransactionDate AS DATETIME) < '2013-03-01' AND t.TransactionTypeID IS NOT NULL GROUP BY t.TransactionTypeID ), tot AS ( SELECT SUM(amt) AS total_amt FROM agg ) SELECT topic, amt, amt / NULLIF((SELECT total_amt FROM tot), 0) AS amt_share FROM agg ORDER BY amt_share DESC;
WITH daily AS ( SELECT DATE( FROM_UNIXTIME(t.RecordedWhen / 1000000)) AS d, COUNT(*) AS cnt FROM WIDE_WORLD_IMPORTERS.WAREHOUSE_VEHICLETEMPERATURES t WHERE FROM_UNIXTIME(t.RecordedWhen / 1000000) >= '2016-03-10' AND FROM_UNIXTIME(t.RecordedWhen / 1000000) < '2016-03-18' GROUP BY d ), ma AS ( SELECT d, cnt, AVG(cnt) OVER (ORDER BY d ROWS BETWEEN 7 PRECEDING AND 1 PRECEDING) AS prev_7d_avg FROM daily ) SELECT d, cnt, prev_7d_avg FROM ma WHERE prev_7d_avg IS NOT NULL AND cnt > prev_7d_avg ORDER BY (cnt - prev_7d_avg) DESC;
SELECT l.StockItemID, SUM(CASE WHEN l.IsOrderLineFinalized = '1' THEN 1 ELSE 0 END) AS hit_cnt, COUNT(*) AS total_cnt, SUM(CASE WHEN l.IsOrderLineFinalized = '1' THEN 1 ELSE 0 END) / COUNT(*) AS hit_ratio FROM WIDE_WORLD_IMPORTERS.PURCHASING_PURCHASEORDERLINES l WHERE l.StockItemID IS NOT NULL GROUP BY l.StockItemID HAVING COUNT(*) >= 50 ORDER BY hit_ratio DESC LIMIT 3;
SELECT s.StockItemID, COUNT(DISTINCT s.Barcode) AS external_cnt FROM WIDE_WORLD_IMPORTERS.WAREHOUSE_STOCKITEMS s GROUP BY s.StockItemID HAVING COUNT(DISTINCT s.Barcode) > 1 ORDER BY external_cnt DESC LIMIT 10;
SELECT i.InvoiceID AS id_external FROM WIDE_WORLD_IMPORTERS.SALES_INVOICES i WHERE COALESCE(i.ReturnedDeliveryData, '') LIKE '%Ready for collection%' or '%EventTime%' LIMIT 5;
WITH agg AS ( SELECT bg.BuyingGroupName AS topic, c.CustomerName AS entity_name, COUNT(*) AS qty FROM WIDE_WORLD_IMPORTERS.SALES_CUSTOMERS c JOIN WIDE_WORLD_IMPORTERS.SALES_BUYINGGROUPS bg ON c.BuyingGroupID = bg.BuyingGroupID WHERE c.CustomerName IS NOT NULL GROUP BY bg.BuyingGroupName, c.CustomerName ), ranked AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY topic ORDER BY qty DESC, entity_name) AS rn FROM agg ) SELECT topic, entity_name, qty FROM ranked WHERE rn = 1 ORDER BY qty DESC;
SELECT t.DeliveryMethodID AS category_topic, COUNT(*) AS event_cnt FROM WIDE_WORLD_IMPORTERS.PURCHASING_PURCHASEORDER t WHERE str_to_date(t.OrderDate, '%Y-%m-%d') >= '2014-01-01' AND str_to_date(t.OrderDate, '%Y-%m-%d') < '2016-01-01' AND COALESCE(t.Comments, '') LIKE '%undecided%' GROUP BY t.DeliveryMethodID ORDER BY event_cnt DESC LIMIT 10;
SELECT i.DeliveryInstructions AS location, i.DeliveryMethodID AS category_topic, COUNT(*) AS event_cnt FROM WIDE_WORLD_IMPORTERS.SALES_INVOICES i WHERE i.DeliveryInstructions IS NOT NULL AND i.DeliveryMethodID IS NOT NULL GROUP BY i.DeliveryInstructions, i.DeliveryMethodID HAVING COUNT(*) >= 10 ORDER BY event_cnt DESC LIMIT 20;
SELECT COUNT(DISTINCT t.ORG_ID) AS distinct_entity_cnt FROM 数管平台.原油商品量月动态表 t WHERE t.ORG_ID IS NOT NULL;
SELECT t.ORG_ID, COUNT(*) AS event_cnt FROM 数管平台.原油销售日报 t WHERE t.ORG_ID IS NOT NULL AND t.REPORT_FORM_DAILY_ID IS NOT NULL GROUP BY t.ORG_ID ORDER BY event_cnt DESC LIMIT 1000;
SELECT COUNT(*) AS event_cnt FROM `数管平台`.`原油日产量(A8 2.0)` t WHERE t.ORDER_DATE >= '2024-01-01 00:00:00' AND t.ORDER_DATE < '2024-01-31 23:59:59';
SELECT t.BWART, COUNT(*) AS event_cnt FROM `数管平台`.`原油日商品量(A8 2.0)` t WHERE t.BWART IS NOT NULL GROUP BY t.BWART ORDER BY event_cnt DESC LIMIT 1000;
SELECT t.ENERGY_SORT, SUM(t.MONTH_MERCHANDISE_VOLUME) AS total_amount FROM 数管平台.原油商品量月动态表 t WHERE t.ENERGY_SORT IS NOT NULL AND t.MONTH_MERCHANDISE_VOLUME IS NOT NULL GROUP BY t.ENERGY_SORT ORDER BY total_amount DESC LIMIT 1000;
SELECT t.REPORT_FORM_DAILY_ID, COUNT(DISTINCT t.ORG_ID) AS entity_cnt FROM `数管平台`.`原油销售日报` t WHERE t.REPORT_FORM_DAILY_ID IS NOT NULL GROUP BY t.REPORT_FORM_DAILY_ID HAVING COUNT(DISTINCT t.ORG_ID) > 1 ORDER BY entity_cnt DESC LIMIT 3;
WITH a AS ( SELECT DISTINCT t.SGTXT FROM `数管平台`.`原油日产量(A8 2.0)` t WHERE t.SGTXT IS NOT NULL AND t.ORDER_DATE >= '2025-01-01 00:00:00' AND t.ORDER_DATE < '2025-01-03 00:00:00' ), b AS ( SELECT DISTINCT t.SGTXT FROM `数管平台`.`原油日产量(A8 2.0)` t WHERE t.SGTXT IS NOT NULL AND t.ORDER_DATE >= '2025-01-05 00:00:00' AND t.ORDER_DATE < '2025-01-07 00:00:00' ) SELECT COUNT(*) AS retained_entity_cnt FROM a JOIN b USING (SGTXT);
SELECT t.BWART, SUM(CASE WHEN t.ORDER_DATE >= '2025-01-01 00:00:00' AND t.ORDER_DATE < '2025-01-03 00:00:00' THEN 1 ELSE 0 END) AS curr_cnt, SUM(CASE WHEN t.ORDER_DATE >= '2025-01-05 00:00:00' AND t.ORDER_DATE < '2025-01-07 00:00:00' THEN 1 ELSE 0 END) AS prev_cnt, ( SUM(CASE WHEN t.ORDER_DATE >= '2025-01-01 00:00:00' AND t.ORDER_DATE < '2025-01-03 00:00:00' THEN 1 ELSE 0 END) - SUM(CASE WHEN t.ORDER_DATE >= '2025-01-05 00:00:00' AND t.ORDER_DATE < '2025-01-07 00:00:00' THEN 1 ELSE 0 END) ) AS delta_cnt FROM `数管平台`.`原油日商品量(A8 2.0)` t WHERE t.BWART IS NOT NULL GROUP BY t.BWART ORDER BY delta_cnt DESC LIMIT 3;
WITH agg AS ( SELECT t.BWTAR AS topic, SUM(t.AMOUNT) AS amt FROM `数管平台`.`原油月产量(A8 2.0)` t WHERE CAST(t.ORDER_DATE AS DATETIME) >= '2025-01-01 00:00:00' AND CAST(t.ORDER_DATE AS DATETIME) < '2025-02-01 00:00:00' AND t.BWTAR IS NOT NULL GROUP BY t.BWTAR ), tot AS ( SELECT SUM(amt) AS total_amt FROM agg ) SELECT topic, amt, amt / NULLIF((SELECT total_amt FROM tot), 0) AS amt_share FROM agg ORDER BY amt_share DESC;
WITH daily AS ( SELECT DATE( t.DATA_DATE) AS d, COUNT(*) AS cnt FROM `数管平台`.`原油销售日报` t WHERE CAST(t.DATA_DATE AS DATETIME) >= '2025-01-21 00:00:00' AND CAST(t.DATA_DATE AS DATETIME) < '2025-01-28 00:00:00' GROUP BY d ), ma AS ( SELECT d, cnt, AVG(cnt) OVER (ORDER BY d ROWS BETWEEN 7 PRECEDING AND 1 PRECEDING) AS prev_7d_avg FROM daily ) SELECT d, cnt, prev_7d_avg FROM ma WHERE prev_7d_avg IS NOT NULL AND cnt > prev_7d_avg ORDER BY (cnt - prev_7d_avg) DESC;
SELECT t.UNIFY_TASK_ID, SUM(CASE WHEN t.APPROVAL_STATUS = 0 THEN 0 ELSE 1 END) AS hit_cnt, COUNT(*) AS total_cnt, SUM(CASE WHEN t.APPROVAL_STATUS = 0 THEN 0 ELSE 1 END) / COUNT(*) AS hit_ratio FROM 数管平台.原油销售日报 t WHERE t.UNIFY_TASK_ID IS NOT NULL GROUP BY t.UNIFY_TASK_ID ORDER BY hit_ratio DESC LIMIT 3;
SELECT t.COMPANY AS id_external FROM 数管平台.公司代码信息 t WHERE COALESCE(t.ZZTP_REMK, '') LIKE '%海外单位%' LIMIT 5;
WITH agg AS ( SELECT t.ENERGY_SORT AS topic, t.ORG_NAME AS entity_name, SUM(t.MONTH_MERCHANDISE_VOLUME) AS amt FROM 数管平台.原油商品量月动态表 t WHERE t.ENERGY_SORT IS NOT NULL AND t.ORG_NAME IS NOT NULL AND t.MONTH_MERCHANDISE_VOLUME IS NOT NULL GROUP BY t.ENERGY_SORT, t.ORG_NAME ), ranked AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY topic ORDER BY amt DESC, entity_name) AS rn FROM agg ) SELECT topic, entity_name, amt FROM ranked WHERE rn = 1 ORDER BY amt DESC;
SELECT t.PROJ_TYPE AS category_topic, COUNT(*) AS event_cnt FROM 数管平台.原油销售日报 t WHERE str_to_date(t.DATA_DATE, '%Y-%m-%d') >= '2025-01-01' AND str_to_date(t.DATA_DATE, '%Y-%m-%d') < '2025-03-01' AND t.REMARKS = 1 GROUP BY t.PROJ_TYPE ORDER BY event_cnt DESC LIMIT 10;
SELECT t.DATA_REGION AS location, t.ENERGY_SORT AS category_topic, COUNT(*) AS event_cnt FROM 数管平台.原油商品量月动态表 t WHERE t.DATA_REGION IS NOT NULL AND t.ENERGY_SORT IS NOT NULL GROUP BY t.DATA_REGION, t.ENERGY_SORT HAVING COUNT(*) >= 10 ORDER BY event_cnt DESC LIMIT 20;
